import sys
import os
import subprocess
import pickle

def read_commands(command_file):
    with open(command_file, 'r', encoding='utf-8') as f:
        return [line.strip() for line in f if line.strip()]

def load_cache(cache_file):
    if not os.path.exists(cache_file):
        return {}
    try:
        with open(cache_file, 'rb') as f:
            return pickle.load(f)
    except (pickle.PickleError, IOError):
        return {}

def save_cache(cache_file, cache):
    with open(cache_file, 'wb') as f:
        pickle.dump(cache, f)

def process_command(command, cache):
    if command in cache:
        print(cache[command].decode('utf-8'), end='')
        return

    try:
        result = subprocess.run(
            command,
            shell=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=False,
            check=True
        )
        cache[command] = result.stdout
        print(result.stdout.decode('utf-8'), end='')
    except subprocess.CalledProcessError as e:
        print(f"ERROR {command}: ", file=sys.stderr)
        print(e.stderr.decode('utf-8'), file=sys.stderr)

def main():
    if len(sys.argv) != 3:
        print("Usage: python cmd_cache.py <command_file> <cache_file>", file=sys.stderr)
        sys.exit(1)

    command_file = sys.argv[1]
    cache_file = sys.argv[2]

    commands = read_commands(command_file)
    cache = load_cache(cache_file)

    for command in commands:
        process_command(command, cache)

    save_cache(cache_file, cache)

if __name__ == "__main__":
    main()

import sys
import os
import json
import subprocess
from typing import Dict, Optional

def read_commands(command_file: str) -> list[str]:
    with open(command_file, 'r', encoding='utf-8') as f:
        return [line.strip() for line in f if line.strip()]

def process_commands(commands: list[str], cache_file: str, cache: Dict[str, bytes]) -> None:
    for cmd in commands:
        if cmd in cache:
            sys.stdout.buffer.write(cache[cmd])
            continue

        try:
            result = subprocess.run(
                cmd,
                shell=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=False,
                check=True
            )
            cache[cmd] = result.stdout
            sys.stdout.buffer.write(result.stdout)
        except subprocess.CalledProcessError as e:
            sys.stderr.write(f"{cmd}: {e.stderr.decode('utf-8', errors='replace')}\n".encode('utf-8'))

def load_cache(cache_file: str) -> Dict[str, bytes]:
    if not os.path.exists(cache_file):
        return {}

    try:
        with open(cache_file, 'rb') as f:
            return json.load(f)
    except (json.JSONDecodeError, IOError):
        return {}

def save_cache(cache_file: str, cache: Dict[str, bytes]) -> None:
    with open(cache_file, 'wb') as f:
        json.dump(cache, f)

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    command_file = sys.argv[1]
    cache_file = sys.argv[2]

    commands = read_commands(command_file)
    cache = load_cache(cache_file)

    process_commands(commands, cache_file, cache)
    save_cache(cache_file, cache)

if __name__ == "__main__":
    main()

import sys
import os
import pickle
import subprocess

def main():
    if len(sys.argv) != 3:
        print("Usage: python cmd_cache.py <command_file> <cache_file>", file=sys.stderr)
        sys.exit(1)

    command_file = sys.argv[1]
    cache_file = sys.argv[2]

    # Load or initialize cache
    cache = {}
    if os.path.exists(cache_file):
        try:
            with open(cache_file, 'rb') as f:
                cache = pickle.load(f)
        except (pickle.PickleError, IOError):
            cache = {}

    # Process each command
    with open(command_file, 'r', encoding='utf-8') as f:
        for line in f:
            cmd = line.strip()
            if not cmd:
                continue

            if cmd in cache:
                print(cache[cmd], end='')
                sys.exit(0)

            try:
                result = subprocess.run(cmd, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=False)
                stdout = result.stdout
                if result.returncode == 0:
                    cache[cmd] = stdout
                    with open(cache_file, 'wb') as f:
                        pickle.dump(cache, f)
                sys.exit(0)
            except Exception:
                sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import os
import pickle
import subprocess

def main():
    if len(sys.argv) != 3:
        print("Usage: python cmd_cache.py <command_file> <cache_file>")
        sys.exit(1)

    command_file = sys.argv[1]
    cache_file = sys.argv[2]

    # Load commands from file
    commands = []
    with open(command_file, 'r', encoding='utf-8') as f:
        for line in f:
            stripped = line.strip()
            if stripped:
                commands.append(stripped)

    # Load cache if exists
    cache = {}
    if os.path.exists(cache_file):
        try:
            with open(cache_file, 'rb') as f:
                cache = pickle.load(f)
        except (pickle.PickleError, EOFError):
            cache = {}

    # Process commands
    for cmd in commands:
        if cmd in cache:
            print(cache[cmd], end='')
        else:
            result = subprocess.run(cmd, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=False)
            print(result.stdout, end='')
            cache[cmd] = result.stdout

    # Save cache
    with open(cache_file, 'wb') as f:
        pickle.dump(cache, f)

if __name__ == "__main__":
    main()
